1	// 已提交命令的键值应用：把日志命令解释为 set/delete 键值操作，在本次调用内
2	// 从空键值表开始，随提交位置推进按日志索引顺序应用。本文件只做纯逻辑处理。
3	package mevwatch
4	
5	import (
6		"strings"
7		"unicode"
8	)
9	
10	// 键值命令格式错误的原因（稳定标识符，帮助文档中有说明）。
11	const (
12		ApplyReasonUnknownCommand   = `invalid command: expected "set <key>=<value>" or "delete <key>"`
13		ApplyReasonEmptyKey         = "invalid command: key is empty"
14		ApplyReasonKeyHasWhitespace = "invalid command: key contains whitespace"
15		ApplyReasonKeyHasEquals     = "invalid command: key contains '='"
16		ApplyReasonSetMissingEquals = "invalid command: set requires '=' between key and value"
17	)
18	
19	// ApplyError 描述已提交命令中第一个格式错误：出错条目的日志索引与具体原因。
20	type ApplyError struct {
21		Index  int    `json:"index"`
22		Reason string `json:"reason"`
23	}
24	
25	// kvOperation 是一条解析成功的键值命令。
26	type kvOperation struct {
27		isDelete bool
28		key      string
29		value    string // 仅 set 使用；按原文保留，允许为空
30	}
31	
32	// parseKVCommand 把一条命令解释为键值操作，失败时返回具体原因。
33	// 命令区分大小写，命令名后必须恰好有一个普通空格；键不能为空、不能含空白
34	// 或等号；set 以键后的第一个等号分隔值，值按原文保留（可为空、含空格、
35	// 中文及额外等号）。命令两端不做任何空白裁剪。
36	func parseKVCommand(command string) (kvOperation, string) {
37		if rest, ok := strings.CutPrefix(command, "set "); ok {
38			eq := strings.IndexByte(rest, '=')
39			if eq < 0 {
40				return kvOperation{}, ApplyReasonSetMissingEquals
41			}
42			key, value := rest[:eq], rest[eq+1:]
43			if reason := validateKVKey(key); reason != "" {
44				return kvOperation{}, reason
45			}
46			return kvOperation{key: key, value: value}, ""
47		}
48		if rest, ok := strings.CutPrefix(command, "delete "); ok {
49			if reason := validateKVKey(rest); reason != "" {
50				return kvOperation{}, reason
51			}
52			return kvOperation{isDelete: true, key: rest}, ""
53		}
54		return kvOperation{}, ApplyReasonUnknownCommand
55	}
56	
57	// validateKVKey 校验键：不能为空、不能含空白或等号。
58	func validateKVKey(key string) string {
59		if key == "" {
60			return ApplyReasonEmptyKey
61		}
62		for _, r := range key {
63			if unicode.IsSpace(r) {
64				return ApplyReasonKeyHasWhitespace
65			}
66			if r == '=' {
67				return ApplyReasonKeyHasEquals
68			}
69		}
70		return ""
71	}
72	
73	// kvApplier 在本次调用内从空键值表开始，按日志索引顺序应用已提交命令。
74	// 一旦遇到格式错误，应用状态停住：已应用索引不再前进，错误保留到调用结束。
75	type kvApplier struct {
76		kv           map[string]string
77		appliedIndex int         // 已应用的最高日志索引，0 表示尚未应用任何条目
78		err          *ApplyError // 非空后应用状态停住
79	}
80	
81	func newKVApplier() *kvApplier {
82		return &kvApplier{kv: map[string]string{}}
83	}
84	
85	// applyUpTo 应用 (appliedIndex, committedIndex] 区间内尚未应用的已提交条目。
86	// 只前进不后退：空条目心跳、重复复制、提交位置不变时不会重复应用；已出错时
87	// 不再应用任何条目。未提交的条目不在此触及，其格式错误不会提前暴露。
88	func (a *kvApplier) applyUpTo(log []LogEntry, committedIndex int) {
89		if a.err != nil {
90			return
91		}
92		for a.appliedIndex < committedIndex {
93			next := a.appliedIndex + 1
94			op, reason := parseKVCommand(log[next-1].Command)
95			if reason != "" {
96				// 保留此前已成功应用的结果，已应用索引停在出错位置的前一条。
97				a.err = &ApplyError{Index: next, Reason: reason}
98				return
99			}
100			if op.isDelete {
101				delete(a.kv, op.key) // 删除不存在的键同样算成功，该位置照常标记已应用
102			} else {
103				a.kv[op.key] = op.value
104			}
105			a.appliedIndex = next
106		}
107	}
108

