1	// Raft 跟随者本地日志复制：在单次命令调用内维护节点状态，顺序应用
2	// 领导者发来的 AppendEntries 请求。本文件只做纯逻辑处理，不连接网络。
3	package mevwatch
4	
5	import (
6		"encoding/json"
7		"fmt"
8	)
9	
10	// LogEntry 是一条日志：Index 从 1 开始连续编号，Term 为该条目写入时的任期，
11	// Command 为字符串命令。
12	type LogEntry struct {
13		Index   int    `json:"index"`
14		Term    int    `json:"term"`
15		Command string `json:"command"`
16	}
17	
18	// InitialState 是跟随者在本次调用开始时的状态。
19	type InitialState struct {
20		// CurrentTerm 是该节点已知的最新任期。
21		CurrentTerm int `json:"currentTerm"`
22		// CommittedIndex 是已经提交（不可覆盖）的最高日志索引。
23		CommittedIndex int `json:"committedIndex"`
24		// Log 是从索引 1 开始的连续日志。
25		Log []LogEntry `json:"log"`
26	}
27	
28	// AppendRequest 是顺序到达的一次日志复制请求。
29	type AppendRequest struct {
30		// Term 是领导者任期。
31		Term int `json:"term"`
32		// PrevLogIndex / PrevLogTerm 是新条目紧邻的前一条日志的索引与任期；
33		// 均为 0 表示日志起点（哨兵），不是真实条目。
34		PrevLogIndex int `json:"prevLogIndex"`
35		PrevLogTerm  int `json:"prevLogTerm"`
36		// Entries 是待追加的条目，必须从前一条索引加 1 开始连续排列，允许为空。
37		Entries []LogEntry `json:"entries"`
38		// LeaderCommit 是领导者已提交索引。
39		LeaderCommit int `json:"leaderCommit"`
40	}
41	
42	// AppendResult 是单条请求处理后节点对该请求的答复。
43	type AppendResult struct {
44		// Accepted 表示本次复制是否成功。
45		Accepted bool `json:"accepted"`
46		// Reason 是成功 ok 或被拒绝的具体原因。
47		Reason string `json:"reason"`
48		// Term 是处理后节点的当前任期（较高任期请求即便最终被拒绝也会留下任期更新）。
49		Term int `json:"term"`
50		// CommittedIndex 是处理后节点的已提交索引。
51		CommittedIndex int `json:"committedIndex"`
52		// AppliedIndex / ApplyError 仅在启用键值应用（ReplicateOptions.ApplyKV）
53		// 时填充：处理本请求后已应用的最高日志索引与首个应用错误。
54		// 复制是否被接受与命令应用是否失败相互独立表达。
55		AppliedIndex *int        `json:"appliedIndex,omitempty"`
56		ApplyError   *ApplyError `json:"applyError,omitempty"`
57		// applyFields 为 true 时 JSON 输出总是带上 appliedIndex 与 applyError
58		// （无错误时 applyError 为 null）；为 false 时两个字段完全不出现。
59		applyFields bool
60	}
61	
62	// MarshalJSON 在未启用键值应用时保持原有输出形状；启用时强制输出
63	// appliedIndex 与 applyError（错误为空输出 null）。
64	func (r AppendResult) MarshalJSON() ([]byte, error) {
65		type alias AppendResult
66		if !r.applyFields {
67			return json.Marshal(alias(r))
68		}
69		applied := 0
70		if r.AppliedIndex != nil {
71			applied = *r.AppliedIndex
72		}
73		return json.Marshal(struct {
74			alias
75			AppliedIndex int         `json:"appliedIndex"`
76			ApplyError   *ApplyError `json:"applyError"`
77		}{
78			alias:        alias(r),
79			AppliedIndex: applied,
80			ApplyError:   r.ApplyError,
81		})
82	}
83	
84	// ReplicateOutput 是整次调用的结果。
85	type ReplicateOutput struct {
86		// Results 与输入请求一一对应。
87		Results []AppendResult `json:"results"`
88		// FinalTerm / FinalCommittedIndex 是最终状态。
89		FinalTerm           int `json:"finalTerm"`
90		FinalCommittedIndex int `json:"finalCommittedIndex"`
91		// FinalLog 是处理完所有请求后的完整日志。
92		FinalLog []LogEntry `json:"finalLog"`
93		// FinalAppliedIndex / FinalKV / FinalApplyError 仅在启用键值应用时填充：
94		// 最终已应用的最高日志索引、最终键值表与首个应用错误。没有请求时同样
95		// 反映初始已提交前缀的应用结果。
96		FinalAppliedIndex *int              `json:"finalAppliedIndex,omitempty"`
97		FinalKV           map[string]string `json:"finalKV,omitempty"`
98		FinalApplyError   *ApplyError       `json:"finalApplyError,omitempty"`
99		// applyFields 含义同 AppendResult.applyFields。
100		applyFields bool
101	}
102	
103	// MarshalJSON 在未启用键值应用时保持原有输出形状；启用时强制输出
104	// finalAppliedIndex、finalKV（空表为 {}）与 finalApplyError（无错误为 null）。
105	func (o ReplicateOutput) MarshalJSON() ([]byte, error) {
106		type alias ReplicateOutput
107		if !o.applyFields {
108			return json.Marshal(alias(o))
109		}
110		applied := 0
111		if o.FinalAppliedIndex != nil {
112			applied = *o.FinalAppliedIndex
113		}
114		kv := o.FinalKV
115		if kv == nil {
116			kv = map[string]string{}
117		}
118		return json.Marshal(struct {
119			alias
120			FinalAppliedIndex int               `json:"finalAppliedIndex"`
121			FinalKV           map[string]string `json:"finalKV"`
122			FinalApplyError   *ApplyError       `json:"finalApplyError"`
123		}{
124			alias:             alias(o),
125			FinalAppliedIndex: applied,
126			FinalKV:           kv,
127			FinalApplyError:   o.FinalApplyError,
128		})
129	}
130	
131	// 拒绝原因（稳定标识符，帮助文档中有说明）。
132	const (
133		ReasonOK                      = "ok"
134		ReasonStaleTerm               = "stale term: leader term is lower than current term"
135		ReasonRequestTermNegative     = "invalid request: term is negative"
136		ReasonPrevLogIndexNegative    = "invalid request: prevLogIndex is negative"
137		ReasonPrevLogTermNegative     = "invalid request: prevLogTerm is negative"
138		ReasonLeaderCommitNegative    = "invalid request: leaderCommit is negative"
139		ReasonEmptyEntryTerm          = "invalid request: log entry has zero term"
140		ReasonEntryIndexGap           = "invalid request: entries are not consecutive from prevLogIndex+1"
141		ReasonEntryTermDecreases      = "invalid request: entry terms are not non-decreasing"
142		ReasonEntryTermExceedsReqTerm = "invalid request: entry term exceeds request term"
143		ReasonPrevLogMismatch         = "prev log mismatch: entry at prevLogIndex is missing or has a different term"
144		ReasonCommandConflictSameTerm = "entry conflict: same index and term but different command"
145		ReasonWouldOverwriteCommitted = "would overwrite committed entry"
146	)
147	
148	type replicateState struct {
149		currentTerm    int
150		committedIndex int
151		log            []LogEntry // log[i].Index == i+1
152	}
153	
154	// ReplicateOptions 控制 Replicate 的可选行为。零值保持原有处理与输出。
155	type ReplicateOptions struct {
156		// ApplyKV 为 true 时把已提交命令解释为键值操作（set/delete），在本次
157		// 调用内从空键值表开始，随提交位置推进按日志次序逐条应用；为 false
158		// 时命令仍是不加解释的任意字符串。
159		ApplyKV bool
160	}
161	
162	// Replicate 校验初始状态并顺序应用全部复制请求，返回逐次结果与最终状态。
163	// 初始状态非法时返回错误（调用方应以非零退出码结束）。单条请求违反字段规则
164	// 时只记录一次拒绝、不改变任何状态，随后继续处理下一条请求。
165	func Replicate(initial InitialState, requests []AppendRequest) (ReplicateOutput, error) {
166		return ReplicateWithOptions(initial, requests, ReplicateOptions{})
167	}
168	
169	// ReplicateWithOptions 与 Replicate 相同，但可通过 ReplicateOptions 启用
170	// 可选行为（如键值应用）。
171	func ReplicateWithOptions(initial InitialState, requests []AppendRequest, opts ReplicateOptions) (ReplicateOutput, error) {
172		state, err := newReplicateState(initial)
173		if err != nil {
174			return ReplicateOutput{}, err
175		}
176	
177		var applier *kvApplier
178		if opts.ApplyKV {
179			applier = newKVApplier()
180			// 先按索引顺序应用初始日志中已提交的前缀，再顺序处理复制请求。
181			applier.applyUpTo(state.log, state.committedIndex)
182		}
183	
184		results := make([]AppendResult, 0, len(requests))
185		for _, request := range requests {
186			result := state.apply(request)
187			if applier != nil {
188				// 每条请求处理结束后，只应用新提交且尚未应用的日志；应用失败
189				// 不改变复制的接受与否、提交位置或拒绝原因。
190				applier.applyUpTo(state.log, state.committedIndex)
191				applied := applier.appliedIndex
192				result.AppliedIndex = &applied
193				result.ApplyError = applier.err
194				result.applyFields = true
195			}
196			results = append(results, result)
197		}
198		finalLog := append([]LogEntry{}, state.log...)
199		if finalLog == nil {
200			finalLog = []LogEntry{}
201		}
202		output := ReplicateOutput{
203			Results:             results,
204			FinalTerm:           state.currentTerm,
205			FinalCommittedIndex: state.committedIndex,
206			FinalLog:            finalLog,
207		}
208		if applier != nil {
209			applied := applier.appliedIndex
210			output.FinalAppliedIndex = &applied
211			output.FinalKV = applier.kv
212			output.FinalApplyError = applier.err
213			output.applyFields = true
214		}
215		return output, nil
216	}
217	
218	func newReplicateState(initial InitialState) (replicateState, error) {
219		if initial.CurrentTerm < 0 {
220			return replicateState{}, fmt.Errorf("invalid initial state: currentTerm must be a non-negative integer")
221		}
222		if initial.CommittedIndex < 0 {
223			return replicateState{}, fmt.Errorf("invalid initial state: committedIndex must be a non-negative integer")
224		}
225		if initial.CommittedIndex > len(initial.Log) {
226			return replicateState{}, fmt.Errorf("invalid initial state: committedIndex %d exceeds log length %d", initial.CommittedIndex, len(initial.Log))
227		}
228		log := append([]LogEntry(nil), initial.Log...)
229		for i, entry := range log {
230			expected := i + 1
231			if entry.Index != expected {
232				return replicateState{}, fmt.Errorf("invalid initial state: log entry %d has non-consecutive index %d", expected, entry.Index)
233			}
234			if entry.Term <= 0 {
235				return replicateState{}, fmt.Errorf("invalid initial state: log entry %d has non-positive term %d", expected, entry.Term)
236			}
237			if i > 0 && entry.Term < log[i-1].Term {
238				return replicateState{}, fmt.Errorf("invalid initial state: log entry %d term %d is lower than previous term %d", expected, entry.Term, log[i-1].Term)
239			}
240			if entry.Term > initial.CurrentTerm {
241				return replicateState{}, fmt.Errorf("invalid initial state: log entry %d term %d exceeds currentTerm %d", expected, entry.Term, initial.CurrentTerm)
242			}
243		}
244		return replicateState{
245			currentTerm:    initial.CurrentTerm,
246			committedIndex: initial.CommittedIndex,
247			log:            log,
248		}, nil
249	}
250	
251	// termAt 返回索引 idx 处条目的任期；idx 为 0 时是日志起点哨兵，超出日志长度时 ok 为 false。
252	func (s *replicateState) termAt(idx int) (term int, ok bool) {
253		switch {
254		case idx == 0:
255			return 0, true
256		case idx < 0 || idx > len(s.log):
257			return 0, false
258		default:
259			return s.log[idx-1].Term, true
260		}
261	}
262	
263	// apply 处理单条请求。整个操作是原子的：任何拒绝都不会在日志、已提交索引上
264	// 留下部分变更；唯一例外是较高任期带来的 currentTerm 更新，按规则必须保留。
265	func (s *replicateState) apply(request AppendRequest) AppendResult {
266		snapshot := *s
267		accepted, reason := s.tryApply(request)
268		if !accepted {
269			// 回滚日志与提交位置；较高任期更新（若已发生）保留在 s.currentTerm 中。
270			s.log = snapshot.log
271			s.committedIndex = snapshot.committedIndex
272		}
273		return AppendResult{
274			Accepted:       accepted,
275			Reason:         reason,
276			Term:           s.currentTerm,
277			CommittedIndex: s.committedIndex,
278		}
279	}
280	
281	func (s *replicateState) tryApply(request AppendRequest) (bool, string) {
282		// 规则 1：先做字段合法性校验。违反字段规则的请求只记录拒绝、不改变任何
283		// 状态——即使它携带更高任期，也不能更新节点。
284		if reason := validateRequest(request); reason != ReasonOK {
285			return false, reason
286		}
287	
288		// 规则 2：较低任期直接拒绝，状态（含任期）完全不变。
289		if request.Term < s.currentTerm {
290			return false, ReasonStaleTerm
291		}
292	
293		// 规则 3：首条目任期不得低于前一条日志任期（整段日志必须不下降）。
294		// 这仍属于字段规则，放在任期更新之前：非法请求不能借高任期改变节点。
295		if len(request.Entries) > 0 && request.Entries[0].Term < request.PrevLogTerm {
296			return false, ReasonEntryTermDecreases
297		}
298	
299		// 规则 4：较高任期先更新当前任期，再核对日志；之后即便因前缀不匹配被拒，
300		// 任期更新也保留。
301		if request.Term > s.currentTerm {
302			s.currentTerm = request.Term
303		}
304	
305		// 规则 5：前一条日志必须存在且任期相同。索引 0 始终只与任期 0 匹配。
306		prevTerm, ok := s.termAt(request.PrevLogIndex)
307		if !ok || prevTerm != request.PrevLogTerm {
308			return false, ReasonPrevLogMismatch
309		}
310	
311		// 规则 6：把待追加条目与现有位置逐一比对——全部检查通过后才落笔，
312		// 保证“即使前面已发现可追加内容，也不能留下部分变更”。第一个任期冲突
313		// 位置之后的旧日志都会被整段替换，因此只需在冲突位置之前检查命令冲突。
314		// matched 是请求条目中与现有位置完全相同（同任期同命令）的连续前缀长度；
315		// 超出本地日志长度的位置尚不存在，不属于已匹配，稍后追加。
316		start := request.PrevLogIndex // entries[k] 对应索引 start+1+k
317		cutAt := -1                   // 首个任期不同的现有位置（切片下标）
318		matched := 0
319		for offset, incoming := range request.Entries {
320			idx := start + 1 + offset
321			if idx > len(s.log) {
322				break // 该位置及之后都不存在：稍后整体追加
323			}
324			existing := s.log[idx-1]
325			switch {
326			case existing.Term == incoming.Term && existing.Command == incoming.Command:
327				// 完全相同：保留，重复请求不会产生重复条目。
328				matched++
329			case existing.Term == incoming.Term:
330				// 同索引同任期却命令不同：拒绝，日志与提交位置保持原样。
331				return false, ReasonCommandConflictSameTerm
332			case idx <= s.committedIndex:
333				// 不同任期意味着要覆盖该处及其后缀；已提交条目不可覆盖。
334				return false, ReasonWouldOverwriteCommitted
335			default:
336				// 未提交位置上的任期冲突：截断到此处再追加，其后旧日志整段丢弃。
337				cutAt = idx - 1
338			}
339			if cutAt >= 0 {
340				break
341			}
342		}
343	
344		// 规则 7：合并日志。全部匹配的短请求（matched == len(entries)）不删除
345		// 本地多出的尾部；任期冲突时截断冲突位置及其后缀；其余缺失位置追加。
346		if cutAt >= 0 {
347			matched = cutAt - start
348			s.log = append([]LogEntry(nil), s.log[:cutAt]...)
349		}
350		if matched < len(request.Entries) {
351			s.log = append(s.log, request.Entries[matched:]...)
352		}
353	
354		// 规则 8：提交位置推进至 leaderCommit 与本次确认的最后索引的较小值，
355		// 且不会后退。空条目请求的确认位置就是前一条索引。
356		lastIndex := request.PrevLogIndex + len(request.Entries)
357		newCommit := request.LeaderCommit
358		if lastIndex < newCommit {
359			newCommit = lastIndex
360		}
361		if newCommit > s.committedIndex {
362			s.committedIndex = newCommit
363		}
364		return true, ReasonOK
365	}
366	
367	func validateRequest(request AppendRequest) string {
368		if request.Term < 0 {
369			return ReasonRequestTermNegative
370		}
371		if request.PrevLogIndex < 0 {
372			return ReasonPrevLogIndexNegative
373		}
374		if request.PrevLogTerm < 0 {
375			return ReasonPrevLogTermNegative
376		}
377		if request.LeaderCommit < 0 {
378			return ReasonLeaderCommitNegative
379		}
380		// 条目必须从前一条索引加 1 开始连续排列；任期为正、沿请求条目自身
381		// 不下降，且不得超过请求（领导者）任期。与 prevLogTerm 的衔接在
382		// tryApply 中单独检查。索引 0 是哨兵，真实条目索引必为正。
383		for i, entry := range request.Entries {
384			if entry.Index != request.PrevLogIndex+1+i {
385				return ReasonEntryIndexGap
386			}
387			if entry.Term <= 0 {
388				return ReasonEmptyEntryTerm
389			}
390			if i > 0 && entry.Term < request.Entries[i-1].Term {
391				return ReasonEntryTermDecreases
392			}
393			if entry.Term > request.Term {
394				return ReasonEntryTermExceedsReqTerm
395			}
396		}
397		return ReasonOK
398	}
