341		if err != nil {
342			t.Fatal(err)
343		}
344		encoded2, err := json.Marshal(second)
345		if err != nil {
346			t.Fatal(err)
347		}
348		if string(encoded1) != string(encoded2) {
349			t.Fatalf("non-deterministic JSON:\n%s\n%s", encoded1, encoded2)
350		}
351	}
